@if($paginator->hasPages())<nav aria-label="Pagination" class="pagination-controls">@if($paginator->onFirstPage())<span>← Previous</span>@else<a href="{{ $paginator->previousPageUrl() }}" @if(isset($this)) wire:click.prevent="previousPage('{{ $paginator->getPageName() }}')" @endif>← Previous</a>@endif<span>Page {{ $paginator->currentPage() }} of {{ $paginator->lastPage() }}</span>@if($paginator->hasMorePages())<a href="{{ $paginator->nextPageUrl() }}" @if(isset($this)) wire:click.prevent="nextPage('{{ $paginator->getPageName() }}')" @endif>Next →</a>@else<span>Next →</span>@endif</nav>@else<span class="small muted">{{ $paginator->total() }} records</span>@endif
